"""Every rounding rule of meterbill lives here."""

from __future__ import annotations

import math
from decimal import ROUND_DOWN, ROUND_HALF_EVEN, ROUND_HALF_UP, Decimal

CENT = Decimal("0.01")
HALF_UP = "half_up"
HALF_EVEN = "half_even"
DOWN = "down"

_METHODS = {HALF_UP: ROUND_HALF_UP, HALF_EVEN: ROUND_HALF_EVEN, DOWN: ROUND_DOWN}


def _check(value, step, method) -> None:
    if not isinstance(value, Decimal) or not isinstance(step, Decimal):
        raise TypeError("value and step must be Decimal")
    if not isinstance(method, str) or method not in _METHODS:
        raise ValueError(f"unknown rounding method: {method!r}")
    if not step.is_finite() or not step > 0:
        raise ValueError("step must be positive")


def round_amount(value: Decimal, step: Decimal, method: str) -> Decimal:
    """The multiple of `step` nearest to `value`; `method` decides ties/direction."""
    _check(value, step, method)
    if not value.is_finite():
        return value.quantize(step, rounding=_METHODS[method])
    sign, digits, exp = value.as_tuple()
    _, sdigits, sexp = step.as_tuple()
    coef = int("".join(map(str, digits)))
    scoef = int("".join(map(str, sdigits)))
    shift = exp - sexp
    if shift >= 0:
        num, den = coef * 10**shift, scoef
    else:
        num, den = coef, scoef * 10**-shift
    q, r = divmod(num, den)
    if method != DOWN:
        twice = 2 * r
        if twice > den:
            q += 1
        elif twice == den:
            if method == HALF_UP or q % 2 == 1:
                q += 1
    result = q * scoef
    return Decimal((sign, tuple(int(c) for c in str(result)), sexp))


def allocate(amounts: list[Decimal], step: Decimal) -> list[Decimal]:
    """Cut each amount down to `step`; the loss against the rounded total goes
    on the last part whose amount is not zero."""
    amounts = list(amounts)
    parts = [round_amount(a, step, DOWN) for a in amounts]
    whole = round_amount(sum(amounts, Decimal("0")), step, HALF_UP)
    rest = whole - sum(parts, round_amount(Decimal("0"), step, DOWN))
    for i in range(len(parts) - 1, -1, -1):
        if amounts[i] != 0:
            parts[i] += rest
            break
    return parts


def legacy_cents(value: float, places: int = 2) -> float:
    """Binary floating point settling of the old customer system."""
    scale = 10**places
    return math.floor(value * scale + 0.5) / scale


def fixed(value: float | Decimal, places: int, method: str = HALF_EVEN) -> str:
    """`value` with `places` digits after the point."""
    if isinstance(value, Decimal):
        if method not in _METHODS:
            raise ValueError(f"unknown rounding method: {method!r}")
        if not value.is_finite():
            return format(value, "f")
        return format(round_amount(value, Decimal(1).scaleb(-places), method), "f")
    if isinstance(value, float):
        if method != HALF_EVEN:
            raise ValueError("a float is only written half to even")
        return format(value, f".{places}f")
    raise TypeError("value must be float or Decimal")
